WITH lines AS (SELECT id, customer_id, created_at, coupon_codes, pos, entry.qty, entry.price, entry.promo FROM carts LATERAL VIEW POSEXPLODE(items) x AS pos, entry) SELECT id, customer_id, pos, qty, price, SUM(qty) OVER (PARTITION BY customer_id ORDER BY created_at, id, pos ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_qty, SUM(qty) OVER (ORDER BY pos, id, pos ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_qty_2, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY created_at DESC, id, pos) AS row_seq, AVG(qty) OVER (ORDER BY created_at, id, pos ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS qty_avg_3, NTILE(5) OVER (PARTITION BY promo ORDER BY pos DESC, id, pos) AS pos_bucket FROM lines
